<?php
declare(strict_types=1);require __DIR__.'/automation-engine.php';if(PHP_SAPI!=='cli'){http_response_code(403);exit('CLI only');}$cid=(int)($argv[1]??0);if($cid<1){fwrite(STDERR,"Usage: php ami-listener.php COMPANY_ID\n");exit(2);}$cfg=integration_settings($cid,'voip');$s=$cfg['settings'];if(!$cfg['enabled']||empty($s['ami_host'])||empty($s['username'])){fwrite(STDERR,"VoIP/AMI is not configured for company $cid\n");exit(2);}$pdo=db();
while(true){$fp=@fsockopen((string)$s['ami_host'],(int)($s['ami_port']??5038),$errno,$errstr,10);if(!$fp){fwrite(STDERR,"AMI connect failed: $errstr\n");sleep(5);continue;}stream_set_timeout($fp,60);$user=preg_replace('/[\r\n]/','',(string)$s['username']);$secret=preg_replace('/[\r\n]/','',(string)($s['secret']??$s['password']??''));fwrite($fp,"Action: Login\r\nUsername: $user\r\nSecret: $secret\r\nEvents: on\r\n\r\n");$event=[];while(!feof($fp)){$line=fgets($fp,4096);if($line===false)break;$line=rtrim($line,"\r\n");if($line!==''){if(str_contains($line,':')){[$k,$v]=array_map('trim',explode(':',$line,2));$event[$k]=$v;}continue;}if(!isset($event['Event'])||!in_array($event['Event'],['Newchannel','DialBegin'],true)){$event=[];continue;}$phone=preg_replace('/[^0-9+]/','',(string)($event['CallerIDNum']??''));$extension=preg_replace('/[^A-Za-z0-9_.-]/','',(string)($event['Exten']??$event['DestCallerIDNum']??''));$uid=(string)($event['Uniqueid']??$event['Linkedid']??'');if($phone===''||$phone===$extension){$event=[];continue;}$st=$pdo->prepare('SELECT 1 FROM v10_call_logs WHERE company_id=? AND external_id=? LIMIT 1');$st->execute([$cid,$uid]);if($uid!==''&&$st->fetchColumn()){$event=[];continue;}$userId=null;if($extension!==''){$st=$pdo->prepare('SELECT id FROM users WHERE company_id=? AND extension=? AND active=1 LIMIT 1');$st->execute([$cid,$extension]);$userId=$st->fetchColumn()?:null;}$contact=null;$customer=null;$needle='%'.substr($phone,-8);$st=$pdo->prepare("SELECT id,customer_id FROM contacts WHERE company_id=? AND REPLACE(REPLACE(phone,' ',''),'-','') LIKE ? LIMIT 1");$st->execute([$cid,$needle]);if($r=$st->fetch()){$contact=$r['id'];$customer=$r['customer_id'];}if(!$customer){$st=$pdo->prepare("SELECT id FROM customers WHERE company_id=? AND REPLACE(REPLACE(phone,' ',''),'-','') LIKE ? LIMIT 1");$st->execute([$cid,$needle]);$customer=$st->fetchColumn()?:null;}$pdo->prepare("INSERT INTO v10_call_logs(company_id,user_id,customer_id,contact_id,direction,phone,external_id,status,notes) VALUES(?,?,?,?,?,?,?,'ringing',?)")->execute([$cid,$userId,$customer,$contact,'inbound',$phone,$uid,'AMI '.$event['Event'].'; extension:'.$extension]);$event=[];}fclose($fp);sleep(2);}
